findings.fix_proposal:
Distinguish the two None cases at the call site or in the helper, e.g.:

pub(crate) fn parse_sse_data(data: &str) -> Option<StreamEvent> {
    if data == "[DONE]" {
        return None;
    }
    match serde_json::from_str(data) {
        Ok(ev) => Some(ev),
        Err(e) => {
            tracing::debug!(target: "aleph::openai_responses_sse", error = %e, frame = %data, "dropping unparseable SSE frame");
            None
        }
    }
}
